#!/usr/bin/env python3
"""Build the private, localhost-only 100-template review gallery."""
import argparse,collections,copy,json,shutil
from pathlib import Path
from PIL import Image,ImageOps,ImageDraw,ImageFont

HTML='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GenSticker · 100 模板 A/B 实测</title><style>
:root{font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;color:#17253b;background:#f2f5f9}*{box-sizing:border-box}body{margin:0}header{padding:30px max(24px,calc((100vw - 1400px)/2));background:#10233c;color:white}h1{margin:4px 0 10px;font-size:30px}p{line-height:1.7;margin:7px 0}.sub{color:#c0cddc;font-size:14px}.stats{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0 5px}.stat{background:#203852;border:1px solid #38526a;border-radius:12px;padding:13px 20px;min-width:140px}.stat b{display:block;font-size:28px}.stat span{font-size:12px;color:#b9cadc}main{max-width:1450px;margin:auto;padding:22px}.note{background:white;border-radius:12px;padding:16px 20px;border-left:4px solid #d59c37;margin:0 0 18px;font-size:14px}.sources{display:flex;gap:9px;overflow:auto;padding:2px 0 15px}.source{border:2px solid transparent;background:white;border-radius:10px;padding:6px;cursor:pointer;min-width:92px}.source.active{border-color:#467cf4}.source img{width:78px;height:78px;object-fit:contain}.source small{display:block;text-align:center}.toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;position:sticky;top:0;background:#f2f5f9f5;padding:12px 0;z-index:2}input,select,button{font:inherit;font-size:14px;padding:9px 12px;border-radius:8px;border:1px solid #ced8e2;background:white;color:#18314b}input{min-width:220px}button{cursor:pointer}button:hover{border-color:#467cf4}a{color:#3264bd}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(305px,1fr));gap:16px}.card{background:white;border:1px solid #dce4ed;border-radius:13px;overflow:hidden;cursor:pointer}.card:hover{border-color:#7399e7;box-shadow:0 5px 20px #11233c15}.cardhead{padding:13px 14px 8px;display:flex;gap:8px;align-items:flex-start;justify-content:space-between}.title{font-size:16px;font-weight:600}.id{font-size:11px;color:#738297;margin-bottom:4px}.badge{border-radius:5px;padding:3px 7px;background:#e9f0ff;color:#285aab;font-size:12px;white-space:nowrap}.badge.B{background:#f1eafd;color:#7544af}.images{display:grid;grid-template-columns:1fr 1fr;background:#e8edf2;gap:1px}.images img{width:100%;height:182px;object-fit:contain;background:#fafbfd}.labels{display:flex;justify-content:space-around;color:#7d899b;font-size:11px;padding:4px}.cardfoot{font-size:12px;color:#687a90;padding:10px 14px;line-height:1.8}.good{color:#24825b}.warn{color:#ad7425}.bad{color:#c14c57}.modal{position:fixed;inset:0;z-index:10;background:#17253b99;display:none;align-items:flex-start;justify-content:center;padding:24px;overflow:auto}.modal.open{display:flex}.panel{background:#f3f6fa;border-radius:15px;max-width:1200px;width:100%;padding:22px}.modalhead{display:flex;gap:20px;justify-content:space-between;align-items:start}.original{width:150px;max-height:150px;object-fit:contain;background:white;border-radius:8px}.compare{display:grid;grid-template-columns:100px 1fr 1fr;gap:12px;padding:15px;background:white;border-radius:10px;margin:12px 0}.compare img{width:100%;height:280px;object-fit:contain;background:#f7f9fb}.compare .inputimg{height:180px}.label{color:#6c7e94;font-size:13px;margin-bottom:8px}.rating{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.rating button{font-size:12px;padding:6px 9px}.rating button.chosen{background:#244b83;color:white}.small{font-size:12px;color:#738297}.close{position:sticky;top:12px;float:right}.scheme{display:grid;grid-template-columns:1fr 1fr;gap:20px}.scheme strong{font-size:15px}.warning{color:#a66b21}.footer{font-size:12px;color:#6f8095;margin:24px 0}#count{font-size:13px;color:#66788e;min-width:80px}@media(max-width:700px){h1{font-size:23px}.compare{grid-template-columns:65px 1fr 1fr;gap:7px;padding:8px}.compare img{height:190px}.compare .inputimg{height:100px}.modal{padding:6px}.panel{padding:12px}.scheme{grid-template-columns:1fr}.original{width:90px}.stat{min-width:110px;padding:10px}}
</style><header><div class="sub">GENSTICKER · 固定随机分配 · 完整失败与回退记录</div><h1>100 个模板 × 6 张照片，逐项评估 A / B</h1><p class="sub">A、B 各抽 50 个，抽样先于模板检测与渲染。同一模板始终使用同一效果。结果包含原生 Python 和声明式配方。</p><div class="stats" id="stats"></div></header><main><div class="note"><div class="scheme"><div><strong>A · 适中融合</strong><p>保留更多上传照片的五官，通过几何变形带入模板表情；必要时借用模板嘴内纹理。固定强度 0.58。</p></div><div><strong>B · 表情优先</strong><p>较强地转移模板表情，并移植原模板的嘴部组件；嘴唇、牙齿等可能来自模板。固定强度 0.94。</p></div></div><p class="warning" id="coverage"></p><p class="small">“已融合”表示算法实际执行，不代表视觉验收。侧脸、眼镜、夸张嘴型、动物和动漫脸可能出现拉伸、硬边或身份变化。GIF 可点开查看完整动画和逐帧图。保护像素检查发生在 GIF 调色板编码之前。</p></div><div class="sources" id="sources"></div><div class="toolbar"><input id="search" placeholder="搜索模板名 / 编号"><select id="mode"><option value="">A + B</option><option>A</option><option>B</option></select><select id="adapter"><option value="">所有生成路径</option><option value="declarative">声明式配方</option><option value="native-input">原生 Python</option></select><select id="status"><option value="">全部结果</option><option value="fused">实际执行融合</option><option value="fallback">回退原算法</option><option value="failed">渲染失败</option></select><button id="export">导出我的评价</button><a href="data.json" download>测试记录</a><span id="count"></span></div><div class="grid" id="grid"></div><div class="footer" id="footer"></div></main><div class="modal" id="modal"><div class="panel"><button class="close" id="close">关闭 ×</button><div id="detail"></div></div></div><script>
let DATA,SAMPLE='S03';const $=id=>document.getElementById(id),ratings=JSON.parse(localStorage.getItem('gensticker-ab100-review-v1')||'{}');function el(tag,cls,text){let n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}function img(file,cls){let n=el('img',cls);n.src=file;n.loading='lazy';return n}function media(file){return 'media/'+encodeURIComponent(file)}function status(c){return c.status==='fused'?'已融合':c.status==='fallback'?'回退原算法':'渲染失败'}function rating(row,c){let box=el('div','rating');for(let text of ['可用','需调整','不可用']){let key=c.template+'-'+c.sample,b=el('button',ratings[key]===text?'chosen':'',text);b.onclick=e=>{e.stopPropagation();ratings[key]=text;localStorage.setItem('gensticker-ab100-review-v1',JSON.stringify(ratings));box.replaceWith(rating(row,c))};box.append(b)}return box}function render(){let query=$('search').value.trim().toLowerCase(),shown=0;$('grid').replaceChildren();for(let t of DATA.templates){let c=DATA.cases.find(c=>c.template===t.id&&c.sample===SAMPLE);if(!c)continue;if(query&&!(t.id+' '+t.name).toLowerCase().includes(query)||$('mode').value&&t.mode!==$('mode').value||$('adapter').value&&t.adapter!==$('adapter').value||$('status').value&&c.status!==$('status').value)continue;shown++;let card=el('div','card'),head=el('div','cardhead'),title=el('div');title.append(el('div','id',t.id+' · v'+t.base_version+' → v'+t.version),el('div','title',t.name));head.append(title,el('span','badge '+t.mode,t.mode));let images=el('div','images');for(let variant of ['baseline','result']){let file=c[variant];images.append(file?img('thumbs/'+t.id+'-'+SAMPLE+'-'+(variant==='baseline'?'before':'after')+'.jpg'):el('div','bad',c.error||'未生成'))}let labels=el('div','labels');labels.append(el('span','','修改前'),el('span','','修改后 · '+t.mode));let foot=el('div','cardfoot');foot.append(el('span',c.status==='fused'?'good':c.status==='failed'?'bad':'warn',status(c)),el('div','',t.adapter==='declarative'?'声明式配方':'原生 Python'));if(c.result)foot.append(el('div','small',c.result.size.join('×')+' · '+c.result.frames+' 帧 · '+Math.round(c.render_ms)+' ms'));foot.append(rating(t,c));card.append(head,images,labels,foot);card.onclick=()=>detail(t);$('grid').append(card)}$('count').textContent=shown+' / 100 个模板'}function detail(t){let d=$('detail');d.replaceChildren();let head=el('div','modalhead'),title=el('div');title.append(el('div','id',t.id+' · '+t.key),el('h2','',t.name+' · 效果 '+t.mode),el('p','small',t.adapter+' · 表情区域 '+t.supported_regions+'/'+t.regions+' · '+t.reasons.join(' / ')));if(t.preview)head.append(title,img(media(t.preview),'original'));else head.append(title);d.append(head);for(let s of DATA.samples){let c=DATA.cases.find(c=>c.template===t.id&&c.sample===s);if(!c)continue;let row=el('div','compare'),source=el('div');source.append(el('div','label',s),img('sources/'+s+'.png','inputimg'));row.append(source);for(let variant of ['baseline','result']){let cell=el('div');cell.append(el('div','label',variant==='baseline'?'修改前':'修改后 · '+status(c)));if(c[variant]){cell.append(img(media(c[variant].file)));let link=el('a','small','打开原尺寸文件');link.href=media(c[variant].file);link.target='_blank';cell.append(link)}else cell.append(el('p','bad',c.error||'未生成'));if(variant==='result'){cell.append(el('p','small',(c.render_ms||0)+' ms · '+(c.applied_regions||0)+' 个区域执行融合'));if(c.result?.frames>1){let link=el('a','small','查看完整逐帧对比');link.href='contacts/'+t.id+'-'+s+'.jpg';link.target='_blank';cell.append(link)}cell.append(rating(t,c));let folds=Math.max(0,...(c.metrics||[]).map(m=>m.folded_triangles||0));if(folds)cell.append(el('p','warning','存在几何折叠记录（最大 '+folds+'），请重点检查五官形变。'))}row.append(cell)}d.append(row)}let link=el('a','small','下载此模板六张照片的静态对比图');link.href='comparisons/'+t.id+'.jpg';link.target='_blank';d.append(link);$('modal').classList.add('open')}
$('close').onclick=()=>$('modal').classList.remove('open');$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').classList.remove('open')};document.onkeydown=e=>{if(e.key==='Escape')$('modal').classList.remove('open')};for(let id of ['search','mode','adapter','status'])$(id).oninput=render;$('export').onclick=()=>{let payload={seed:DATA.selection.seed,ratings,templates:DATA.templates.map(t=>({id:t.id,key:t.key,mode:t.mode,version:t.version})),created:new Date().toISOString()},a=el('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download='GenSticker-100模板-我的评价.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};fetch('data.json').then(r=>r.json()).then(d=>{DATA=d;let counts=d.counts;for(let [value,label] of [[100,'测试模板'],[600,'模板 × 照片组合'],[counts.fused||0,'实际执行融合'],[counts.fallback||0,'回退原算法'],[counts.failed||0,'渲染失败']]){let box=el('div','stat');box.append(el('b','',value),el('span','',label));$('stats').append(box)}$('coverage').textContent='当前库：'+d.library.total+' 个带图模板，A / B 各 '+d.library.per_mode+' 个；'+d.library.supported+' 个有可用表情配方，'+(d.library.total-d.library.supported)+' 个保留回退。纯文字模板不受这次修改影响。';for(let s of d.samples){let button=el('button','source'+(s===SAMPLE?' active':''));button.append(img('sources/'+s+'.png'),el('small','',s));button.onclick=()=>{SAMPLE=s;for(let b of $('sources').children)b.classList.remove('active');button.classList.add('active');render()};$('sources').append(button)}$('footer').textContent='实测范围：本机 CPU，包含照片分析与编码，不包含网络和队列。尺寸异常 '+d.dimension_mismatches+'，时序异常 '+d.timeline_mismatches+'。测试图片和结果仅存放于本机私有目录；评价保存在此浏览器。';render()});
</script></html>'''


def main():
    p=argparse.ArgumentParser();p.add_argument('--evaluation',type=Path,required=True);p.add_argument('--compiled',type=Path,required=True);p.add_argument('--inputs',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
    report=json.loads((a.evaluation/'report.json').read_text());items=json.loads((a.compiled/'compiled.json').read_text());a.output.mkdir(parents=True,exist_ok=True)
    for name in ['sources','thumbs','contacts','comparisons']:(a.output/name).mkdir(exist_ok=True)
    media=a.output/'media'
    if not media.exists():media.symlink_to(a.evaluation/'media',target_is_directory=True)
    for s in report['samples']:shutil.copy2(a.inputs/(s+'.png'),a.output/'sources'/(s+'.png'))
    fontpath=next((p for p in [Path('/System/Library/Fonts/STHeiti Light.ttc'),Path('/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc')] if p.exists()),None)
    font=ImageFont.truetype(str(fontpath),17) if fontpath else ImageFont.load_default()
    for t in report['templates']:
        sheet=Image.new('RGB',(900,6*270+45),'#edf1f6');draw=ImageDraw.Draw(sheet);draw.text((15,12),t['id']+' '+t['name']+' / '+t['mode'],font=font,fill='#17253b')
        for j,sample in enumerate(report['samples']):
            c=next(c for c in report['cases'] if c['template']==t['id'] and c['sample']==sample);paths=[a.inputs/(sample+'.png')]
            for v in ['baseline','result']:
                if c.get(v):paths.append(a.evaluation/'media'/c[v]['file'])
                else:paths.append(None)
            for col,path in enumerate(paths):
                x=col*300;y=j*270+45;label=[sample+' 上传照片','修改前','修改后 '+t['mode']+' / '+c['status']][col];draw.text((x+10,y+5),label,font=font,fill='#17253b')
                if path:
                    with Image.open(path) as im:image=ImageOps.contain(im.convert('RGB'),(285,225))
                    sheet.paste(image,(x+(300-image.width)//2,y+32+(225-image.height)//2))
                    if col:
                        thumb=a.output/'thumbs'/(t['id']+'-'+sample+'-'+['','before','after'][col]+'.jpg');thumbimage=ImageOps.contain(image,(320,260));thumbimage.save(thumb,quality=86)
            if c.get('result',{}).get('frames',1)>1 and c.get('baseline'):
                frames=c['result']['frames'];columns=8;rows=(frames+columns-1)//columns;contact=Image.new('RGB',(columns*2*110,rows*132+25),'#edf1f6');cd=ImageDraw.Draw(contact);cd.text((10,4),'每组：修改前 / 修改后 · '+t['id']+' '+sample,font=font,fill='#17253b')
                for half,v in enumerate(['baseline','result']):
                    with Image.open(a.evaluation/'media'/c[v]['file']) as gif:
                        for i in range(gif.n_frames):
                            gif.seek(i);image=ImageOps.contain(gif.convert('RGB'),(106,106));x=(i%columns)*220+half*110;y=(i//columns)*132+25
                            contact.paste(image,(x+(110-image.width)//2,y+18+(106-image.height)//2));cd.text((x+3,y),str(i+1),font=font,fill='#17253b')
                contact.save(a.output/'contacts'/(t['id']+'-'+sample+'.jpg'),quality=84)
        sheet.save(a.output/'comparisons'/(t['id']+'.jpg'),quality=90)
    browser=copy.deepcopy(report)
    for c in browser['cases']:
        for key in ['baseline','result']:
            if c.get(key):c[key].pop('frame_hashes',None)
    browser['library']={'total':len(items),'per_mode':sum(i['metadata']['expression_policy']['mode']=='A' for i in items),'supported':sum(i['metadata']['expression_policy']['supported_regions']>0 for i in items)}
    (a.output/'data.json').write_text(json.dumps(browser,ensure_ascii=False));(a.output/'index.html').write_text(HTML)
    print(json.dumps({'gallery':str(a.output/'index.html'),'cases':len(report['cases']),'counts':report['counts'],'library':browser['library']},ensure_ascii=False))

if __name__=='__main__':main()
